  amount: (json['amount'] as num).toDouble(),
  method:
      $enumDecodeNullable(_$PaymentMethodEnumMap, json['method']) ??
      PaymentMethod.cash,
  transactionId: json['transactionId'] as String? ?? '',
  note: json['note'] as String? ?? '',
  groupId: json['groupId'] as String? ?? '',
